    imageHint: "Hisham Palace mosaic floor Jericho",
    descriptionAdvanced: {
      de: "Der Hischam-Palast, auch bekannt als Khirbat al-Mafjar, ist eines der bedeutendsten Denkmäler der frühen islamischen Architektur in Palästina. Er liegt nördlich von Jericho und wurde im 8. Jahrhundert während der Umayyaden-Dynastie erbaut, wahrscheinlich als luxuriöse Winterresidenz oder Jagdschloss. Der Palastkomplex umfasst ein prachtvolles Badehaus, eine Moschee und einen weitläufigen Innenhof. Weltberühmt ist die Anlage für ihre außergewöhnlichen Mosaike. Das bekannteste Motiv ist der \"Lebensbaum\", der in einem privaten Raum des Badehauses gefunden wurde und einen Baum zeigt, unter dem zwei Gazellen friedlich grasen, während ein Löwe eine dritte Gazelle reißt – ein Symbol für Frieden und Krieg. Ein weiteres architektonisches Highlight ist das sternförmige Fenster, das oft als Wahrzeichen der Anlage dient. Obwohl ein schweres Erdbeben im Jahr 749 den Palast weitgehend zerstörte, bevor er vollständig fertiggestellt war, geben die Ruinen und die meisterhaften Steinmetzarbeiten einen tiefen Einblick in den kulturellen Reichtum der Umayyaden-Zeit. Nach Restaurierungen ist der riesige Mosaikteppich der Thermen heute wieder sichtbar.",
      hu: "A Hisám-palota, más néven Kirbat al-Mafjar, a korai iszlám építészet egyik legkülönlegesebb emléke Palesztinában, Jerikó közelében. A 8. században, az Omajád-dinasztia idején épült komplexum valószínűleg egy uralkodói téli rezidencia és vadászkastély volt, amely a korszak fényűzését tükrözte. A palota hírnevét elsősorban a lenyűgöző padlómozaikjainak köszönheti, amelyek közül kiemelkedik az „Életfa” mozaik. Ez az alkotás egy fát ábrázol, amely alatt két gazella békésen legel, míg a fa másik oldalán egy oroszlán támad meg egy harmadikat, jelképezve a béke és a háború örök kettősségét. Az épületegyüttes része volt egy hatalmas fürdőház, egy mecset és egy díszes udvar is. Bár a 749-es nagy földrengés súlyos károkat okozott az épületben, még mielőtt az teljesen elkészült volna, a megmaradt kőfaragványok és a híres, tízágú csillagot formázó ablakrácsok ma is ámulatba ejtik a látogatókat. A közelmúltbeli felújításoknak köszönhetően a fürdőház hatalmas mozaikpadlója ma már teljes egészében megtekinthető, ami a világ egyik legnagyobb és legépebben maradt ókori mozaikegyüttese.",
      ro: "Palatul lui Hisham, situat în apropiere de Ierihon, reprezintă una dintre cele mai spectaculoase moșteniri ale arhitecturii islamice timpurii. Construit în secolul al VIII-lea sub dinastia Omeiadă, complexul a fost conceput ca un castel de vânătoare și reședință de lux în deșert, oferind o privire asupra stilului de viață sofisticat al califilor. Situl este celebru în întreaga lume pentru mozaicurile sale uluitoare, cel mai cunoscut fiind „Arborele Vieții”. Această operă de artă înfățișează un pom sub care coexistă pacea și violența naturii: două gazele care pasc liniștite și un leu care atacă o a treia victimă. Recent, autoritățile au dezvelit întregul covor de mozaic al băilor termale, o suprafață vastă și incredibil de detaliată care a supraviețuit secolelor. Deși un cutremur devastator în anul 749 a dărâmat mare parte din structuri, ruinele rămase, inclusiv fereastra circulară cu model stelar, sunt de o frumusețe rară. Vizitarea palatului oferă o oportunitate unică de a explora fuziunea dintre tradițiile artistice bizantine și noua estetică islamică, într-unul dintre cele mai vechi orașe din lume.",
      en: "Hisham's Palace, also known as Khirbat al-Mafjar, is a premier site of early Islamic architecture located just north of Jericho. Built in the 8th century during the Umayyad Caliphate, the complex was intended as a grand desert retreat and hunting lodge. It is most famous for its extraordinary mosaic floors, particularly the \"Tree of Life\" mosaic located in a private audience room of the bathhouse. This masterpiece depicts a tree with two gazelles grazing peacefully on one side, while a lion attacks another on the opposite side, symbolizing the duality of peace and war. The complex features a monumental bathhouse, a mosque, and a colonnaded courtyard. Although a massive earthquake in 749 AD severely damaged the palace before its completion, the surviving stonework and the iconic star-shaped window remain hallmarks of Umayyad artistic achievement. Following extensive conservation efforts, the vast mosaic floor of the main hall, one of the largest and best-preserved in the world, is now fully accessible to visitors, showcasing the incredible craftsmanship and cultural synthesis of the early Islamic era.",
      es: "El Palacio de Hisham es un castillo del desierto omeya del siglo VIII, situado al norte de Jericó. Es famoso por sus elaborados mosaicos de suelo, incluido el conocido 'Árbol de la Vida'. El complejo sirvió como residencia de invierno para los califas omeyas antes de ser destruido por un terremoto. Hoy, el sitio es un ejemplo destacado de la arquitectura islámica temprana.",
      pt: "O Palácio de Hisham é um castelo do deserto omíada do século VIII, situado a norte de Jericó. É famoso pelos seus elaborados mosaicos de piso, incluindo o conhecido 'Árvore da Vida'. O complexo serviu como residência de inverno para os califas omíadas antes de ser destruído por um sismo. Hoje, o local é um exemplo importante da arquitetura islâmica primitiva.",
      fr: "Le palais de Hisham est un château du désert omeyyade du VIIIe siècle, situé au nord de Jéricho. Il est réputé pour ses mosaïques de sol élaborées, dont le célèbre « Arbre de Vie ». Le site servait de résidence d'hiver aux califes omeyyades avant d'être détruit par un tremblement de terre. Aujourd'hui, le site est un exemple majeur de l'architecture islamique primitive.",
    },
