      hu: ["Eredetileg 339-ben épült", "UNESCO Világörökség része", "Híres az Alázat Kapujáról", "Bizánci padlómozaikok"],
      ro: ["Construită inițial în 339 d.Hr.", "Patrimoniu Mondial UNESCO", "Include Ușa Umilinței", "Mozaicuri bizantine vechi"],
