      es: ["Construida originalmente en el 339 d.C.", "Patrimonio de la Humanidad de la UNESCO", "Posee la Puerta de la Humildad", "Mosaicos de suelo bizantinos"],
      pt: ["Construída originalmente em 339 d.C.", "Património Mundial da UNESCO", "Possui a Porta da Humildade", "Mosaicos de piso bizantinos"],
