      pt: ["Área total de cerca de 4.100 metros quadrados", "O minarete foi construído no século XIII", "Danos graves causados pelo sismo de 1927", "Napoleão Bonaparte visitou o local no ano de 1799", "O minarete foi destruído em dezembro de 2023", "Outrora local de um templo para o deus Dagon"],
      fr: ["Surface totale d'environ 4 100 mètres carrés", "Le minaret a été construit au XIIIe siècle", "Graves dommages causés par le séisme de 1927", "Napoléon Bonaparte a visité le site en 1799", "Le minaret a été détruit en décembre 2023", "Ancien emplacement d'un temple dédié au dieu Dagon"],
