      pt: ["Construído sob o sultão Baibars no século XIII.", "Napoleão Bonaparte pernoitou aqui no ano 1799.", "É composto por dois andares com paredes maciças de pedra.", "Foi totalmente renovado como museu em 2010.", "Exibe achados desde a Idade do Bronze até ao período romano.", "Possui as típicas abóbadas de aresta mamelucas."],
