      hu: "Ez az észak-gázai rom kivételes mozaikpadlóiról ismert. Az 5. századból származó bizánci templom maradványa.",
      ro: "Această ruină din nordul Gazei este cunoscută pentru mozaicurile sale excepționale. Datează din secolul al V-lea.",
