      pt: ["A primeira fase de construção data do ano 444 d.C.", "Inclui 16 tipos diferentes de motivos de mosaico", "A área da igreja é de cerca de 400 metros quadrados", "Foi reaberta oficialmente em janeiro de 2022", "Os mosaicos mostram aves, gazelas e palmeiras", "Danos graves causados pelo conflito no ano 2023"],
