      ro: "Satul Taybeh adăpostește ruinele bisericii bizantine Sf. Gheorghe. Este identificat ca fiind Efraimul biblic.",
      en: "The village of Taybeh hosts ruins of the Byzantine St. George Church. It is identified as the biblical site of Ephraim.",
      es: "El pueblo de Taybeh alberga ruinas de la iglesia bizantina de San Jorge. Se considera que es el lugar bíblico de Efraín.",
