      en: ["Biblical site of Mizpah", "Ring wall discovered", "Administrative center ruins", "Iron Age archaeological site"],
      es: ["Mizpa bíblica", "Muralla circular descubierta", "Importante centro administrativo", "Hallazgos de la Edad del Hierro"],
