      en: ["Archaeological site Tell Seilun", "Contains Byzantine mosaics", "Destroyed by Philistines", "Major ancient cultic center"],
      es: ["Tell Seilun arqueológico", "Mosaicos bizantinos", "Destruido por los filisteos", "Lugar de culto importante"],
      pt: ["Tell Seilun arqueológico", "Mosaicos bizantinos", "Destruído pelos filisteus", "Local de culto significativo"],
