      en: ["Site of Jacob's dream", "Ruins of a stone tower", "Major pilgrimage center", "Canaanite archaeological roots"],
      es: ["Lugar del sueño de Jacob", "Ruinas de una torre", "Importante lugar de peregrinación", "Orígenes cananeos"],
      pt: ["Local do sonho de Jacob", "Ruínas de uma torre", "Importante local de peregrinação", "Origens cananeias"],
      fr: ["Lieu du songe de Jacob", "Ruines d'une tour", "Lieu de pèlerinage important", "Origines cananéennes"],
