      hu: ["Az első erődítmények i. e. 1550-ből származnak", "850 méteres tengerszint feletti magasságban fekszik", "Az ásatási terület körülbelül 3,5 hektárt tesz ki", "Az első tudományos ásatás 1934-ben kezdődött", "Egy nagy római víztározó maradványait is megtalálták", "Bizánci templomromok láthatók a település keleti részén"],
      ro: ["Primele fortificații datează din anul 1550 î.Hr.", "Situat la o altitudine de 850 de metri deasupra mării", "Situl arheologic cuprinde aproximativ 3,5 hectare", "Prima săpătură științifică a avut loc în anul 1934", "S-au găsit resturile unui rezervor roman mare", "Ruine de biserici bizantine în partea de est a sitului"],
      en: ["First fortifications date to around 1550 BC", "Located at an elevation of 850 meters above sea level", "The archaeological site covers about 3.5 hectares", "First scientific excavation occurred in 1934", "Remains of a large Roman reservoir were discovered", "Byzantine church ruins are located in the east of the site"],
      es: ["Las primeras fortificaciones datan del año 1550 a. C.", "Se encuentra a una altitud de 850 metros sobre el nivel del mar.", "El sitio de excavación cubre unas 3,5 hectáreas.", "La primera excavación científica se realizó en 1934.", "Se hallaron restos de un gran embalse romano.", "Ruinas de iglesias bizantinas en el este de la localidad."],
      pt: ["As primeiras fortificações datam do ano 1550 a.C.", "Situa-se a uma altitude de 850 metros acima do nível do mar.", "O sítio de escavação abrange cerca de 3,5 hectares.", "Primeira escavação científica em 1934.", "Encontrados restos de um grande reservatório romano.", "Ruínas de igrejas bizantinas no leste da localidade."],
      fr: ["Les premières fortifications datent de 1550 av. J.-C.", "Situé à une altitude de 850 mètres au-dessus de la mer.", "Le site archéologique couvre environ 3,5 hectares.", "Premières fouilles scientifiques en 1934.", "Vestiges d'un grand réservoir romain mis au jour.", "Ruines d'églises byzantines à l'est de la localité."],
